import json, random
HEX='0123456789abcdef'
MAXP=4611686018427387903
def hx(rr,n): return ''.join(rr.choice(HEX) for _ in range(2*n))
def gen(seed):
    r = random.Random(seed)
    ntr = r.randint(1,3)
    traces=[]
    for ti in range(ntr):
        cfg = {
            'early': r.random()<0.5,
            'overlap': r.choice(['reject','first']),
            'buffer_packets': r.choice([0,1,1024]),
            'idle_ms': r.choice([0,1,1000000000,3]),
            'max_streams_bidi': r.choice([0,1,1024]),
            'max_streams_uni': r.choice([0,1,1024]),
            'max_stream_data': r.choice([0,1,65536]),
            'max_data': r.choice([0,1,MAXP,3]),
            'crypto_limit': r.choice([0,1,65536,2]),
            'sent': {lv: ([[0,MAXP]] if r.random()<0.5 else ([[0,0]] if r.random()<0.5 else [])) for lv in ('I','H','A')},
        }
        nev=r.randint(1,18); events=[]; t=0
        offs=[0,1,2,126,127,128,129,130,254,255,256,257,383,384,MAXP-3,MAXP-1,MAXP, 2**40, 2**41+7]
        for e in range(nev):
            t += r.choice([0,0,1,2,1000000000])
            k=r.random()
            if k<0.3:
                events.append({'t':t,'op':'key','level':r.choice(['I','H','Z','A']),'action':r.choice(['install','discard'])})
            elif k<0.35:
                events.append({'t':t,'op':'tick'})
            else:
                size=r.choice([0,1199,1200])
                np_=r.randint(1,16)
                pkts=[]
                for i in range(np_):
                    lvl=r.choice(['I','H','Z','A'])
                    nf=r.randint(0,4); frames=[]
                    for j in range(nf):
                        ft=r.choice(['CRYPTO','STREAM','STREAM','RESET_STREAM','STOP_SENDING','ACK','CLOSE','PADDING','UNKNOWN','HANDSHAKE_DONE'])
                        if ft=='CRYPTO':
                            frames.append({'type':'CRYPTO','offset':r.choice(offs),'data_hex':hx(r,r.randint(0,8))})
                        elif ft=='STREAM':
                            frames.append({'type':'STREAM','id':r.choice([0,4,8,2,6,1,3,1023*4,1024*4]),'offset':r.choice(offs),'data_hex':hx(r,r.randint(0,8)),'fin':r.random()<0.5})
                        elif ft=='RESET_STREAM':
                            frames.append({'type':'RESET_STREAM','id':r.choice([0,4,8,2,6,1,3]),'final_size':r.choice([0,1,2,MAXP,MAXP-1])})
                        elif ft=='STOP_SENDING':
                            frames.append({'type':'STOP_SENDING','id':r.choice([0,4,8,2,6,1,3])})
                        elif ft=='ACK':
                            nr=r.randint(0,3); ranges=[]
                            for q in range(nr):
                                lo=r.choice([0,1,MAXP-2,MAXP]); hi=min(MAXP, lo+r.randint(0,3)); ranges.append([lo,hi])
                            frames.append({'type':'ACK','ranges':ranges})
                        elif ft=='CLOSE':
                            frames.append({'type':'CLOSE','app':r.random()<0.5,'code':r.choice([0,MAXP])})
                        else:
                            frames.append({'type':ft})
                    pkts.append({'level':lvl,'pn':r.choice([0,1,MAXP,MAXP-1]),'auth':r.random()<0.8,'frames':frames})
                events.append({'t':t,'op':'datagram','bytes':size,'packets':pkts})
        traces.append({'id':'x%d'%ti,'config':cfg,'events':events})
    return {'version':1,'traces':traces}
EOF
